            check(!CheckpointReferencesR26.hashes(db).contains(CheckpointArtifactsR26.referenceHash(expired)),"Expired parent raw ring remained pinned");files.prune(()->CheckpointReferencesR26.hashes(db),System.currentTimeMillis()+120000,0,256);try{CheckpointArtifactsR26.resolve(store,expired);throw new AssertionError("Expired raw parent remained on disk");}catch(java.io.IOException expected){}
            ExpertExperimentR26.Pair reference;FoundryCampaignR26.Snapshot suffix;try(Cursor row=db.rawQuery("SELECT e.state,f.snapshot FROM r26_expert_experiment e JOIN r26_foundry f ON f.campaign_id=e.campaign_id WHERE e.status='RUNNING'",null)){check(row.moveToFirst(),"No current pair");reference=ExpertExperimentR26.Pair.decode(CheckpointArtifactsR26.resolve(store,row.getBlob(0)));suffix=FoundryCampaignR26.Snapshot.decode(row.getBlob(1));}
